import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import classList from 'flarum/common/utils/classList';
import chatState from '../state/chat';
import ChatSidebar from './ChatSidebar';
import ChannelView from './ChannelView';
import { chatTitle, chatIcon } from '../utils/branding';

/**
 * The floating chat panel, pinned bottom-right over whatever page is open.
 *
 * Mounted once at the app root rather than per-page, so navigating the forum does
 * not tear down an open conversation — which is the entire point of a drawer.
 */
export default class ChatDrawer extends Component {
  view() {
    if (!chatState.drawerOpen) return null;
    const channel = chatState.channel(chatState.activeChannelId);
    const title = chatTitle();
    const icon = chatIcon();
    const unread = chatState.unreadSummary();
    return m("div", {
      className: classList('ChatDrawer', {
        'ChatDrawer--collapsed': chatState.drawerCollapsed
      }),
      role: "complementary",
      "aria-label": title
    }, m("div", {
      className: "ChatDrawer-header",
      onclick: () => this.toggleCollapsed()
    }, channel ? m(Button, {
      className: "Button Button--icon Button--flat",
      icon: "fas fa-chevron-left",
      onclick: e => {
        e.stopPropagation();
        chatState.setActiveChannel(null);
      }
    }) : icon ? m("i", {
      className: icon,
      "aria-hidden": "true"
    }) : null, m("span", {
      className: "ChatDrawer-title"
    }, channel ? channel.displayName() : title), chatState.drawerCollapsed && unread.mentions > 0 ? m("span", {
      className: "ChatDrawer-badge",
      "aria-label": String(unread.mentions)
    }, unread.mentions > 99 ? '99+' : unread.mentions) : chatState.drawerCollapsed && unread.channels > 0 ? m("span", {
      className: "ChatDrawer-dot",
      "aria-hidden": "true"
    }) : null, m("div", {
      className: "ChatDrawer-actions"
    }, m(Button, {
      className: "Button Button--icon Button--flat",
      icon: "fas fa-up-right-and-down-left-from-center",
      title: app.translator.trans('ramon-chat.forum.drawer.full_screen'),
      onclick: e => {
        e.stopPropagation();
        this.goFullScreen();
      }
    }), m(Button, {
      className: "Button Button--icon Button--flat",
      icon: chatState.drawerCollapsed ? 'fas fa-chevron-up' : 'fas fa-chevron-down',
      title: app.translator.trans(chatState.drawerCollapsed ? 'ramon-chat.forum.drawer.expand' : 'ramon-chat.forum.drawer.collapse'),
      onclick: e => {
        e.stopPropagation();
        this.toggleCollapsed();
      }
    }), m(Button, {
      className: "Button Button--icon Button--flat",
      icon: "fas fa-times",
      title: app.translator.trans('ramon-chat.forum.drawer.close'),
      onclick: e => {
        e.stopPropagation();
        this.close();
      }
    }))), chatState.drawerCollapsed ? null : m("div", {
      className: "ChatDrawer-body"
    }, channel ? m(ChannelView, {
      key: channel.id(),
      channel: channel,
      state: chatState
    }) : m(ChatSidebar, {
      state: chatState,
      onSelect: c => this.select(c)
    })));
  }
  select(channel) {
    chatState.setActiveChannel(Number(channel.id()));
    m.redraw();
  }
  toggleCollapsed() {
    chatState.setDrawerCollapsed(!chatState.drawerCollapsed);
    m.redraw();
  }

  /**
   * The only way to close the drawer. Navigating the forum, reloading the page and
   * collapsing the header all leave it open — dismissal has to be deliberate.
   */
  close() {
    chatState.setDrawerOpen(false);
    m.redraw();
  }

  /**
   * Hands the current channel over to the full-screen page. The drawer closes so
   * the two never render the same conversation at once.
   */
  goFullScreen() {
    const id = chatState.activeChannelId;
    chatState.setDrawerOpen(false);
    m.route.set(id ? app.route('chat.channel', {
      id
    }) : app.route('chat.index'));
  }

  /**
   * Opens the drawer, loading the channel list on first open.
   */
  static async open() {
    chatState.setDrawerOpen(true);
    chatState.setDrawerCollapsed(false);
    if (!chatState.channelsLoaded) {
      await Promise.all([chatState.loadChannels(), chatState.loadDrafts()]);
    }
    m.redraw();
  }
}
flarum.reg.add('ramon-chat', 'forum/components/ChatDrawer', ChatDrawer);